import math
import re
from collections import Counter
from pathlib import Path

WORD = re.compile(r"[a-z0-9_]+")


def tokens(text: str) -> list[str]:
    return WORD.findall(text.lower())


def search(kb_dir: str, question: str, limit: int = 5) -> list[str]:
    docs = {str(p.relative_to(kb_dir)): tokens(p.read_text()) for p in Path(kb_dir).rglob("*.md")}
    avg_len = sum(map(len, docs.values())) / len(docs)
    df = Counter(w for words in docs.values() for w in set(words))
    scores = {}
    for path, words in docs.items():
        tf = Counter(words)
        scores[path] = sum(
            math.log(1 + (len(docs) - df[q] + 0.5) / (df[q] + 0.5))
            * tf[q] * 2.2 / (tf[q] + 1.2 * (0.25 + 0.75 * len(words) / avg_len))
            for q in set(tokens(question)) if q in tf
        )
    ranked = sorted(scores, key=lambda p: -scores[p])
    return [p for p in ranked if scores[p] > 0][:limit]
